39	#define MOVBE_BUFFER_SIZE (1 << 14)
40	
41	struct movbe_data {
42	    uint32_t *input;
43	    uint32_t *swapped;
44	};
45	
46	static int movbe_probe_init(struct test *test)
47	{
48	    movbe_data *data = (movbe_data *)malloc(sizeof(movbe_data));
49	    data->input = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
50	    data->swapped = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
51	
52	    for (size_t i = 0; i < MOVBE_BUFFER_SIZE; ++i) {
53	        data->input[i] = random32();
54	    }
55	
56	    test->data = data;
57	    return EXIT_SUCCESS;
58	}
59	
60	static int movbe_probe_cleanup(struct test *test)
61	{
62	    movbe_data *data = (movbe_data *)test->data;
63	    if (data) {
64	        free(data->input);
65	        free(data->swapped);
66	        free(data);
67	    }
68	    return EXIT_SUCCESS;
69	}
