71	// Shared miscompare logger (cold branch only).
72	static void log_miscompare(const char *tag, unsigned i,
73	                           uint32_t inputv, uint32_t golden,
74	                           uint32_t actual, uint32_t xorv)
75	{
76	    unsigned char *ib = (unsigned char *)&inputv;
77	    unsigned char *gb = (unsigned char *)&golden;
78	    unsigned char *ab = (unsigned char *)&actual;
79	    unsigned char *xb = (unsigned char *)&xorv;
80	    log_error("%s: Round-trip failed at index %u: "
81	              "input=0x%08X golden=0x%08X actual=0x%08X xor=0x%08X | "
82	              "bytes[b3 b2 b1 b0] input=%02X%02X%02X%02X "
83	              "golden=%02X%02X%02X%02X actual=%02X%02X%02X%02X "
84	              "xor=%02X%02X%02X%02X",
85	              tag, i, inputv, golden, actual, xorv,
86	              ib[3], ib[2], ib[1], ib[0],
87	              gb[3], gb[2], gb[1], gb[0],
88	              ab[3], ab[2], ab[1], ab[0],
89	              xb[3], xb[2], xb[1], xb[0]);
