93	// ---------------------------------------------------------------------------
94	// movbe_l1d: reload hits L1D.  Hot loop byte-identical to movbe_dump.cpp.
95	// ---------------------------------------------------------------------------
96	static int movbe_l1d_run(struct test *test, int cpu)
97	{
98	    (void)cpu;
99	    movbe_data *data = (movbe_data *)test->data;
100	
101	    TEST_LOOP(test, 1 << 13) {
102	        for (size_t i = 0; i < MOVBE_BUFFER_SIZE; ++i) {
103	            uint32_t val = data->input[i];
104	            val = __builtin_bswap32(val);
105	
106	            data->swapped[i] = val;
107	
108	            val = __builtin_bswap32(val);
109	
110	            if (val != data->input[i]) {
111	                uint32_t inputv = data->input[i];
112	                uint32_t golden = data->input[i];
113	                uint32_t actual = val;
114	                uint32_t xorv = golden ^ actual;
115	                log_miscompare("movbe_l1d", (unsigned)i, inputv, golden, actual, xorv);
116	            }
117	        }
118	    }
