128	// movbe_dump's (it contains the evict), so its own trigger rate may differ;
129	// that is expected and is the point of the comparison.
130	// ---------------------------------------------------------------------------
131	static inline void evict_l1d_line(const void *addr)
132	{
133	    __asm__ volatile(
134	        "dc civac, %0\n\t"
135	        "dsb sy\n\t"
136	        :: "r"(addr) : "memory"
137	    );
138	}
