148	            val = __builtin_bswap32(val);
149	
150	            data->swapped[i] = val;
151	
152	            // Evict input[i]'s cache line from L1D so the reload below
153	            // must fetch from L2/L3 instead of hitting L1D.
154	            evict_l1d_line(&data->input[i]);
155	
156	            val = __builtin_bswap32(val);
157	
158	            if (val != data->input[i]) {
159	                uint32_t inputv = data->input[i];
160	                uint32_t golden = data->input[i];
161	                uint32_t actual = val;
