48	    for (size_t i = 0; i < MOVBE_BUFFER_SIZE; ++i) {
49	        data->input[i] = random32();
50	    }
51	
52	    // Dump the input buffer to a file as the independent golden. This is
53	    // written by core 0's test_init, before any thread (including 179)
54	    // touches the buffer in test_run. Use a fixed path; the harness runs one
55	    // test per invocation here.
56	    int fd = open("/tmp/movbe_input_golden.bin", O_WRONLY | O_CREAT | O_TRUNC, 0644);
57	    if (fd >= 0) {
58	        ssize_t total = 0;
