5	 *
6	 * @test @b mem_disambig_alu
7	 * @parblock
8	 * Variant of mem_disambiguation that adds a data-ALU step before the store,
9	 * to test whether "2-source load + ALU + forwarding at random address" triggers
10	 * SDC. mem_disambiguation already has 2 sources (offsets, values) but stores
11	 * the raw value; this variant stores an ALU result (value op offset).
12	 *
13	 * Diff vs mem_disambiguation: store value from raw values[i] → ALU(values[i] op offsets[i]).
14	 * Skeleton (pattern1) unchanged: store_qword(buffer+off, alu_result); load_qword(buffer+off).
15	 * @endparblock
16	 */
17	
18	#include "sandstone.h"
19	
20	#include <cstdint>
21	
22	#define DISAMBIG_ALU_BUFFER_SIZE   4096
23	#define DISAMBIG_ALU_PATTERN_COUNT  512
24	
25	struct MemDisambigAluData {
26	    uint64_t *offsets;   /* random 8-byte-aligned offsets within buffer */
27	    uint64_t *values;    /* random values to store                       */
28	    uint64_t *expected;  /* expected ALU results                         */
29	};
30	
31	#if defined(__x86_64__) || defined(__i386__)
32	
33	static inline void store_qword(void *addr, uint64_t val)
34	{
35	    __asm__ volatile ("movq %1, %0"
36	        : "=m"(*reinterpret_cast<uint64_t*>(addr))
37	        : "r"(val)
38	        : "memory");
39	}
40	
41	static inline uint64_t load_qword(const void *addr)
42	{
43	    uint64_t result;
44	    __asm__ volatile ("movq %1, %0"
45	        : "=r"(result)
46	        : "m"(*reinterpret_cast<const uint64_t*>(addr))
47	        : "memory");
48	    return result;
49	}
50	
51	#elif defined(__aarch64__)
52	
53	static inline void store_qword(void *addr, uint64_t val)
54	{
55	    __asm__ volatile ("str %1, [%0]"
56	        :
57	        : "r"(addr), "r"(val)
58	        : "memory");
59	}
60	
61	static inline uint64_t load_qword(const void *addr)
62	{
63	    uint64_t result;
64	    __asm__ volatile ("ldr %0, [%1]"
65	        : "=r"(result)
66	        : "r"(addr)
67	        : "memory");
68	    return result;
69	}
70	
71	#endif /* platform */
